import { Route } from '@angular/router';
import { MovieList } from './movie-list/movie-list';

export const appRoutes: Route[] = [
  { path: '', component: MovieList },
  { path: 'screenings/:id/seats', children: [] },
  { path: 'screenings/:id/summary', children: [] },
  { path: 'screenings/:id/checkout', children: [] },
  { path: 'confirmation', children: [] },
  { path: '**', redirectTo: '' },
];

export interface SeatItem {
  kind: 'seat';
  row: number;
  column: number;
  id: string;
  accessible: boolean;
}

export interface CouchItem {
  kind: 'couch';
  row: number;
  start: number;
  end: number;
  ids: [string, string];
}

export type AuditoriumItem = SeatItem | CouchItem;

export interface RowLayout {
  row: number;
  entrance: boolean;
  left: AuditoriumItem[];
  middle: AuditoriumItem[];
  right: AuditoriumItem[];
}

export const ROW_COUNT = 15;
export const COUCH_ROW = 15;

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function isAccessible(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

function seatsIn(row: number, from: number, to: number): SeatItem[] {
  const items: SeatItem[] = [];
  for (let column = from; column <= to; column++) {
    items.push({
      kind: 'seat',
      row,
      column,
      id: seatId(row, column),
      accessible: isAccessible(row, column),
    });
  }
  return items;
}

function couchesIn(row: number, from: number, to: number): CouchItem[] {
  const items: CouchItem[] = [];
  for (let start = from; start <= to; start += 2) {
    const end = start + 1;
    items.push({ kind: 'couch', row, start, end, ids: [seatId(row, start), seatId(row, end)] });
  }
  return items;
}

function rowItems(row: number, from: number, to: number): AuditoriumItem[] {
  return row === COUCH_ROW ? couchesIn(row, from, to) : seatsIn(row, from, to);
}

export function buildAuditorium(): RowLayout[] {
  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const row = index + 1;
    const entrance = row <= 10;
    return {
      row,
      entrance,
      left: entrance ? [] : rowItems(row, 1, 4),
      middle: rowItems(row, 5, 20),
      right: rowItems(row, 21, 24),
    };
  });
}

import { ChangeDetectionStrategy, Component, DestroyRef, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toSignal } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { switchMap } from 'rxjs/operators';
import { CinemaApi } from '../cinema.api';
import { showDate } from '../dates';
import { Movie, Screening } from '../models';
import { AuditoriumItem, CouchItem, SeatItem, buildAuditorium } from './auditorium';

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export const STATE_COLOURS: Record<SeatState, string> = {
  available: '#2E7D32',
  selected: '#F9A825',
  unavailable: '#C62828',
  accessible: '#1565C0',
};

@Component({
  selector: 'app-seat-map',
  templateUrl: './seat-map.html',
  styleUrl: './seat-map.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SeatMap {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly destroyRef = inject(DestroyRef);

  readonly rows = buildAuditorium();
  readonly screening = signal<Screening | null>(null);
  readonly movie = signal<Movie | null>(null);
  readonly subtitle = computed(() => {
    const screening = this.screening();
    return screening ? showDate(screening.date, screening.time) : '';
  });

  private readonly occupied = computed(() => new Set(this.screening()?.occupiedSeats ?? []));

  readonly colours = STATE_COLOURS;

  constructor() {
    const route = inject(ActivatedRoute);
    route.paramMap
      .pipe(
        switchMap((params) => this.api.screening(Number(params.get('id')))),
        switchMap((screening) =>
          this.api.movie(screening.movieId).pipe(switchMap((movie) => [{ screening, movie }])),
        ),
        takeUntilDestroyed(this.destroyRef),
      )
      .subscribe({
        next: ({ screening, movie }) => {
          this.screening.set(screening);
          this.movie.set(movie);
        },
        error: () => void this.router.navigateByUrl('/'),
      });
  }

  stateOf(item: AuditoriumItem): SeatState {
    if (item.kind === 'couch') {
      return this.isOccupied(item.ids[0]) || this.isOccupied(item.ids[1]) ? 'unavailable' : 'available';
    }
    if (this.isOccupied(item.id)) {
      return 'unavailable';
    }
    return item.accessible ? 'accessible' : 'available';
  }

  asSeat(item: AuditoriumItem): SeatItem {
    return item as SeatItem;
  }

  asCouch(item: AuditoriumItem): CouchItem {
    return item as CouchItem;
  }

  private isOccupied(id: string): boolean {
    return this.occupied().has(id);
  }
}

