  back(): void {
    const screening = this.screening();
    if (screening) {
      void this.router.navigateByUrl(`/screenings/${screening.id}/seats`);
    }
  }

  confirm(): void {
    const screening = this.screening();
    if (screening) {
      void this.router.navigateByUrl(`/screenings/${screening.id}/checkout`);
    }
  }
}

