@Component({
  selector: 'app-movie-list',
  imports: [DatePipe, MatButtonModule, MatDatepickerModule, MatInputModule, RouterLink],
  templateUrl: './movie-list.html',
  styleUrl: './movie-list.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
